/// [jwksUrl] URL of the provider's JWKS endpoint used to verify JWTs.
/// [providerName] The name of the authentication provider (e.g., Clerk, Stytch,
///   Auth0)
/// [branchId] The Neon branch ID. Returned as `id` from `GET
///   /projects/{project_id}/branches`.
/// [jwtAudience] Expected `aud` claim in incoming JWTs. When set, tokens with a
///   different audience are rejected; tokens with no audience are still accepted.
///   Omit to skip audience validation.
/// [roleNames] Deprecated. The roles the JWKS should be mapped to. By default,
///   the JWKS is mapped to the `authenticator`, `authenticated`, and `anonymous`
///   roles.
/// [skipRoleCreation] Deprecated. Only used with Neon RLS. If true, role
///   creation is skipped.
Future<JWKSCreationOperation> addProjectJwks(ClientConfig config,
    {required String projectId,
    required String jwksUrl,
    required String providerName,
    SdkOptional<String> branchId = const SdkOmitted(),
    SdkOptional<String> jwtAudience = const SdkOmitted(),
    SdkOptional<List<String>> roleNames = const SdkOmitted(),
    SdkOptional<bool> skipRoleCreation = const SdkOmitted(),
    RequestOptions? requestOptions}) async {
  sdkValidatePattern('project_id', projectId, '^[a-z0-9-]{1,60}\$');
  if (branchId is SdkPresent<String>) {
    sdkValidatePattern('branch_id', branchId.value, '^[a-z0-9-]{1,60}\$');
  }
  if (roleNames is SdkPresent<List<String>>) {
    validateItems('role_names', roleNames.value, min: 0, max: 10);
  }

  return (await sdkRequest<JWKSCreationOperation>(
          'POST', '/projects/${Uri.encodeComponent(projectId.toString())}/jwks',
          config: config,
          body: {
            'jwks_url': jwksUrl,
            'provider_name': providerName,
            'branch_id': SdkUtils.unwrapOptional(branchId),
            'jwt_audience': SdkUtils.unwrapOptional(jwtAudience),
            'role_names': SdkUtils.unwrapOptional(roleNames),
            'skip_role_creation': SdkUtils.unwrapOptional(skipRoleCreation)
          },
          decoder: SdkResponseDecoder.json,
          operationId: 'addProjectJwks',
          fromJsonRaw: (value) =>
              JWKSCreationOperation.fromJson(value as Map<String, dynamic>),
          options: requestOptions,
          errors: {
            'default': (value) =>
                GeneralError.fromJson(value as Map<String, dynamic>)
          }))
      .data;
}

/// Removes the specified JWKS URL from the project. JWTs signed by keys from the removed URL can no longer authenticate to the project's endpoints.
///
/// [projectId] The Neon project ID
/// [jwksId] The JWKS ID
Future<JWKS> deleteProjectJwks(ClientConfig config,
    {required String projectId,
    required String jwksId,
    RequestOptions? requestOptions}) async {
  sdkValidatePattern('project_id', projectId, '^[a-z0-9-]{1,60}\$');

  return (await sdkRequest<JWKS>('DELETE',
          '/projects/${Uri.encodeComponent(projectId.toString())}/jwks/${Uri.encodeComponent(jwksId.toString())}',
          config: config,
          decoder: SdkResponseDecoder.json,
          operationId: 'deleteProjectJwks',
          fromJsonRaw: (value) => JWKS.fromJson(value as Map<String, dynamic>),
          options: requestOptions,
          errors: {
        'default': (value) =>
            GeneralError.fromJson(value as Map<String, dynamic>)
      }))
      .data;
}

/// Retrieves a connection URI for the specified database. The URI uses the standard PostgreSQL connection string format. Set `pooled=true` to include the `-pooler` suffix for a connection pooler URI.
///
/// [projectId] The Neon project ID
/// [databaseName] The database name
/// [roleName] The role name
/// [branchId] The branch ID. Defaults to your project's default `branch_id` if
///   not specified.
/// [endpointId] The endpoint ID. Defaults to the read-write `endpoint_id`
///   associated with the `branch_id` if not specified.
/// [pooled] Adds the `-pooler` option to the connection URI when set to `true`,
///   creating a pooled connection URI.
Future<ConnectionURIResponse> getConnectionUri(ClientConfig config,
    {required String projectId,
    required String databaseName,
    required String roleName,
    SdkOptional<String> branchId = const SdkOmitted(),
    SdkOptional<String> endpointId = const SdkOmitted(),
    SdkOptional<bool> pooled = const SdkOmitted(),
    RequestOptions? requestOptions}) async {
  sdkValidatePattern('project_id', projectId, '^[a-z0-9-]{1,60}\$');
  if (branchId is SdkPresent<String>) {
    sdkValidatePattern('branch_id', branchId.value, '^[a-z0-9-]{1,60}\$');
  }
  if (endpointId is SdkPresent<String>) {
    sdkValidatePattern('endpoint_id', endpointId.value, '^[a-z0-9-]{1,60}\$');
  }

  return (await sdkRequest<ConnectionURIResponse>('GET',
          '/projects/${Uri.encodeComponent(projectId.toString())}/connection_uri',
          config: config,
          query: {
            'database_name':
                SdkQueryValue(databaseName, style: 'form', explode: true),
            'role_name': SdkQueryValue(roleName, style: 'form', explode: true),
            'branch_id': SdkQueryValue(SdkUtils.unwrapOptional(branchId),
                style: 'form', explode: true),
            'endpoint_id': SdkQueryValue(SdkUtils.unwrapOptional(endpointId),
                style: 'form', explode: true),
            'pooled': SdkQueryValue(SdkUtils.unwrapOptional(pooled),
                style: 'form', explode: true)
          },
          decoder: SdkResponseDecoder.json,
          operationId: 'getConnectionUri',
          fromJsonRaw: (value) =>
              ConnectionURIResponse.fromJson(value as Map<String, dynamic>),
          options: requestOptions,
          errors: {
            'default': (value) =>
                GeneralError.fromJson(value as Map<String, dynamic>)
          }))
      .data;
}

